/**
 * client.ts — minimal transport surface consumed by code generated by
 * `spore-gen-ts-client`. Generated <namespace>/client.ts files import
 * these types and call into a `ClientTransport` to launch typed calls.
 *
 * This file ships only the SHAPE of the transport. The actual transport
 * implementation (NDJSON over WebSocket, gRPC bridge, in-process pipe, etc.)
 * is a runtime concern outside this package — Spore's host runtime and
 * the spore-* experiments wire up concrete implementations.
 *
 * The Promise-based API mirrors the gospore exp03 `invokeexp.Call` surface
 * (Done/Err/Value/Next/Final/Cancel) but adapted to JavaScript ergonomics:
 * unary calls resolve their `final()` promise; streaming calls expose a
 * `next()` async iterator-style accessor that resolves to undefined when the
 * stream has emitted its terminal frame.
 */

/** Static info describing a unary callable invocation. Generated client
 *  classes bake these fields in at codegen time. */
export interface UnarySpec {
  namespace: string;
  name: string;
  reqSchemaId: number;
  finalSchemaId: number;
}

/** Static info describing a streaming callable invocation. */
export interface StreamSpec {
  namespace: string;
  name: string;
  reqSchemaId: number;
  chunkSchemaId: number;
  finalSchemaId: number;
}

/** Handle to an in-flight unary call. Resolves `final()` to the response or
 *  rejects on transport / cancel error. */
export interface UnaryCall<Resp> {
  /** Promise of the terminal response. Rejects with the call error
   *  (including cancel) if no value is produced. */
  final(): Promise<Resp>;
  /** Cancel the call. Idempotent. After cancel, `final()` rejects with the
   *  cancel error if it had not already settled. */
  cancel(): void;
}

/** Handle to an in-flight streaming call. */
export interface StreamCall<Chunk, Final> {
  /**
   * Resolve the next streamed chunk. Resolves to `undefined` when the
   * server has emitted its terminal frame — at that point the stream is
   * exhausted and the consumer should call `final()`.
   *
   * Rejects with the call error (including cancel) if the stream fails
   * before emitting a terminal frame.
   */
  next(): Promise<Chunk | undefined>;

  /**
   * Resolve the terminal value. Pending `next()` calls drain to undefined
   * once final() has resolved. Rejects with the call error if the stream
   * ended in failure.
   */
  final(): Promise<Final>;

  /** Cancel the call. Idempotent — sends a cancel frame upstream the
   *  first time it is invoked. */
  cancel(): void;
}

/** ClientTransport is the seam between generated client classes and the
 *  underlying wire transport. Generated code passes a fully-populated
 *  UnarySpec / StreamSpec along with the typed request payload; the
 *  transport encodes the request, allocates a CallID, and returns a typed
 *  call handle whose Promise lifecycle reflects the wire frames. */
export interface ClientTransport {
  unary<Req, Resp>(spec: UnarySpec, req: Req): UnaryCall<Resp>;
  stream<Req, Chunk, Final>(spec: StreamSpec, req: Req): StreamCall<Chunk, Final>;
}
